 P[id]=dict(status=status,reviewedAt='2026-10-29',reviewDepth='Deep source-led review of dated episodes; primary documents read where retrievable; not independently editorially reviewed; not exoneration where no estimate is given',confidence=confidence,period=period,summary=summary,mechanism=mechanism,support=support,counter=counter,limitations=limitations)
